<?php
declare(strict_types=1);
const ROOT = __DIR__ . '/..';
function private_dir(): string { $p = getenv('VT_PRIVATE') ?: dirname(rtrim($_SERVER['DOCUMENT_ROOT'] ?? ROOT, '/\\')) . '/vehicle-tracker-private-' . substr(hash('sha256', realpath(ROOT) ?: ROOT),0,12); if (!is_dir($p)) { if (!mkdir($p,0700,true)) throw new RuntimeException('Cannot create private storage; set VT_PRIVATE to a writable directory outside htdocs.'); } return $p; }
function cfgpath(): string { return private_dir().'/config.php'; }
function installed(): bool { return is_file(private_dir().'/config.lock') && is_file(cfgpath()); }
function config(): array { if (!is_file(cfgpath())) throw new RuntimeException('Website onboarding is incomplete.'); return require cfgpath(); }
function db(?array $c=null): PDO { static $pdo=null; if ($c===null && $pdo) return $pdo; $c=$c??config(); $p=new PDO($c['dsn'],$c['db_user']??null,$c['db_password']??null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]); if(str_starts_with($c['dsn'],'sqlite:')) {$p->exec('PRAGMA foreign_keys=ON'); $p->exec('PRAGMA busy_timeout=10000');} if(is_file(cfgpath()) && $c===config()) $pdo=$p; return $p; }
function sql(PDO $p,string $q,array $v=[]): PDOStatement { $s=$p->prepare($q);$s->execute($v);return $s; }
function schema(PDO $p): void { $mysql=$p->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'; $id=$mysql?'BIGINT PRIMARY KEY AUTO_INCREMENT':'INTEGER PRIMARY KEY AUTOINCREMENT'; $text=$mysql?'LONGTEXT':'TEXT'; foreach([
"CREATE TABLE IF NOT EXISTS meta (name VARCHAR(100) PRIMARY KEY, value $text NOT NULL)",
"CREATE TABLE IF NOT EXISTS users (id $id, username VARCHAR(150) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL)",
"CREATE TABLE IF NOT EXISTS tokens (id $id, user_id BIGINT NOT NULL, hash VARCHAR(64) NOT NULL UNIQUE, label VARCHAR(150) NOT NULL, expires VARCHAR(30) NOT NULL, revoked INTEGER NOT NULL DEFAULT 0)",
"CREATE TABLE IF NOT EXISTS records (id $id, kind VARCHAR(40) NOT NULL, payload $text NOT NULL, version INTEGER NOT NULL DEFAULT 1, created VARCHAR(30) NOT NULL, updated VARCHAR(30) NOT NULL)",
"CREATE TABLE IF NOT EXISTS revisions (id $id, record_id BIGINT NOT NULL, user_id BIGINT NOT NULL, payload $text NOT NULL, action VARCHAR(40) NOT NULL, created VARCHAR(30) NOT NULL)",
"CREATE TABLE IF NOT EXISTS requests (request_key VARCHAR(100) PRIMARY KEY, user_id BIGINT NOT NULL, response $text NOT NULL, created VARCHAR(30) NOT NULL)",
"CREATE TABLE IF NOT EXISTS files (id $id, record_id BIGINT NOT NULL, user_id BIGINT NOT NULL, filename VARCHAR(100) NOT NULL, mime VARCHAR(40) NOT NULL, caption $text NOT NULL, view_label VARCHAR(40) NOT NULL, item_key VARCHAR(80), created VARCHAR(30) NOT NULL)"
] as $q) $p->exec($q.($mysql?' ENGINE=InnoDB DEFAULT CHARSET=utf8mb4':'')); $s=sql($p,'SELECT value FROM meta WHERE name=?',['schema_version'])->fetchColumn(); if(!$s) sql($p,'INSERT INTO meta(name,value) VALUES(?,?)',['schema_version','2']); elseif((int)$s>2) throw new RuntimeException('Database is newer than this application. Do not downgrade.'); }
function json_out($x,int $code=200): never { http_response_code($code);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode($x,JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE);exit; }
function body(): array { $v=json_decode(file_get_contents('php://input'),true); if(!is_array($v)) throw new InvalidArgumentException('Expected a JSON object.');return $v; }
function session_start_safe(): void { if(session_status()!==PHP_SESSION_ACTIVE) { session_name('vehicle_tracker'); session_set_cookie_params(['httponly'=>true,'samesite'=>'Strict','secure'=>(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off'),'path'=>'/']);session_start(); } }
function auth(bool $write=false): int { session_start_safe();$h=$_SERVER['HTTP_AUTHORIZATION']??''; if(preg_match('/^Bearer (.+)$/i',$h,$m)) { $u=sql(db(),'SELECT user_id FROM tokens WHERE hash=? AND revoked=0 AND expires>?',[hash('sha256',$m[1]),gmdate('c')])->fetchColumn(); if(!$u) json_out(['error'=>'Invalid, revoked or expired API token.'],401);return (int)$u; } if(empty($_SESSION['uid'])) json_out(['error'=>'Sign in required.'],401);if($write && !hash_equals($_SESSION['csrf']??'',$_SERVER['HTTP_X_CSRF_TOKEN']??'')) json_out(['error'=>'CSRF token invalid. Refresh the page and retry.'],403);return (int)$_SESSION['uid']; }
function records(?string $kind=null): array { $rows=$kind?sql(db(),'SELECT * FROM records WHERE kind=? ORDER BY id',[$kind])->fetchAll():sql(db(),'SELECT * FROM records ORDER BY id')->fetchAll();return array_map(fn($r)=>['id'=>(int)$r['id'],'kind'=>$r['kind'],'version'=>(int)$r['version'],'created'=>$r['created'],'updated'=>$r['updated'],'data'=>json_decode($r['payload'],true)],$rows); }
function record(int $id): array { $r=sql(db(),'SELECT * FROM records WHERE id=?',[$id])->fetch();if(!$r) throw new InvalidArgumentException('Record not found.');return ['id'=>(int)$r['id'],'kind'=>$r['kind'],'version'=>(int)$r['version'],'data'=>json_decode($r['payload'],true),'created'=>$r['created'],'updated'=>$r['updated']]; }
function num($x,string $label,float $min=0): float { if(!is_numeric($x)||!is_finite((float)$x)||(float)$x<$min||(float)$x>1000000000000) throw new InvalidArgumentException("$label must be a finite number from $min to 1000000000000.");return (float)$x; }
function date_ok($x,string $label='Date'): string { if(!is_string($x)||!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$x)||!checkdate((int)substr($x,5,2),(int)substr($x,8,2),(int)substr($x,0,4))) throw new InvalidArgumentException("$label must be a valid YYYY-MM-DD date.");return $x; }
function required(array $d,array $keys): void {foreach($keys as $key) if(!isset($d[$key])||trim((string)$d[$key])==='') throw new InvalidArgumentException(ucwords(str_replace('_',' ',$key)).' is required.');}
function ref_kind($id,string $kind): array { $r=record((int)$id);if($r['kind']!==$kind) throw new InvalidArgumentException('Invalid '.$kind.' selection.');return $r['data']; }
function checklist(): array { return json_decode(file_get_contents(ROOT.'/data/checklist.json'),true); }
function observations(array $rows,int $vehicle,int $skip=0): array { $o=[];foreach($rows as $r){if($r['id']===$skip)continue;$d=$r['data'];if(($r['kind']==='vehicles'?$r['id']:(int)($d['vehicle_id']??0))!==$vehicle)continue; if($r['kind']==='vehicles')$o[]=['date'=>$d['baseline_date'],'min'=>(float)$d['odometer'],'max'=>(float)$d['odometer'],'source'=>'vehicle baseline #'.$r['id']]; if($r['kind']==='trips')$o[]=['date'=>$d['date'],'min'=>(float)$d['start'],'max'=>(float)$d['end'],'source'=>'trip #'.$r['id']]; if(($r['kind']==='expenses'&&($d['category']??'')==='Fuel'&&isset($d['odometer']))||$r['kind']==='inspections'||$r['kind']==='engines') if(isset($d['odometer'])&&is_numeric($d['odometer'])&&isset($d['date'])) $o[]=['date'=>$d['date'],'min'=>(float)$d['odometer'],'max'=>(float)$d['odometer'],'source'=>$r['kind'].' #'.$r['id']]; }return $o; }
function validate_observation(array $rows,int $vid,int $skip,string $date,float $start,float $end,string $kind): void { foreach(observations($rows,$vid,$skip) as $o){if(str_starts_with($o['source'],'vehicle baseline')&&$o['date']===$date&&$start<$o['min'])throw new InvalidArgumentException('Odometer is below the vehicle baseline on this date.');if(($o['date']<$date && $o['max']>$start)||($o['date']>$date && $o['min']<$end))throw new InvalidArgumentException('Odometer conflicts with '.$o['source'].' on '.$o['date'].' ('.$o['min'].'–'.$o['max'].'). Correct the date or reading; recorded mileage cannot decrease.');if($kind==='trips'&&$o['date']===$date&&str_starts_with($o['source'],'trip')&&$start<$o['max']&&$end>$o['min'])throw new InvalidArgumentException('Trip readings overlap '.$o['source'].'.');} }
function validate(string $kind,array $d,int $id,array $all): array {
 foreach((json_decode(file_get_contents(ROOT.'/data/forms.json'),true)[$kind]['fields']??[]) as $field){$key=$field['key'];if(!array_key_exists($key,$d))continue;if(!is_scalar($d[$key])&&$d[$key]!==null)throw new InvalidArgumentException($field['label'].' must be a single value.');if($field['type']==='checkbox'){if(!in_array($d[$key],[true,false,0,1,'0','1','',null],true))throw new InvalidArgumentException($field['label'].' must be true or false.');$d[$key]=in_array($d[$key],[true,1,'1'],true);}}
 $allowed=['vehicles','trips','expenses','mechanics','invoices','payments','drivers','driver_records','engines','inspections','issues','sales','sale_templates'];if(!in_array($kind,$allowed,true))throw new InvalidArgumentException('Unknown record type.');
 if(isset($d['date'])&&$d['date']!=='')date_ok($d['date']);
 if(in_array($kind,['trips','expenses','invoices','engines','inspections'],true)&&!($kind==='inspections'&&($d['status']??'Draft')==='Draft')){required($d,['vehicle_id']);ref_kind($d['vehicle_id'],'vehicles');}
 if(!empty($d['vehicle_id']))ref_kind($d['vehicle_id'],'vehicles');
 if(!empty($d['driver_id']))ref_kind($d['driver_id'],'drivers');
 if($kind==='vehicles'){required($d,['make','model','year','odometer','baseline_date']);$d['year']=num($d['year'],'Year',1885);if($d['year']>2100)throw new InvalidArgumentException('Invalid year.');$d['odometer']=num($d['odometer'],'Odometer');date_ok($d['baseline_date']);$d['engine_miles']=num($d['engine_miles']??0,'Engine baseline');if($id)validate_observation($all,$id,$id,$d['baseline_date'],$d['odometer'],$d['odometer'],$kind);if(!empty($d['cover_id'])){$f=sql(db(),'SELECT record_id FROM files WHERE id=?',[(int)$d['cover_id']])->fetchColumn();if((int)$f!==$id)throw new InvalidArgumentException('Cover photo must belong to this vehicle.');}}
 if($kind==='trips'){required($d,['date','start','end']);$d['start']=num($d['start'],'Starting odometer');$d['end']=num($d['end'],'Ending odometer',$d['start']);$d['distance']=$d['end']-$d['start'];validate_observation($all,(int)$d['vehicle_id'],$id,$d['date'],$d['start'],$d['end'],$kind);}
 if($kind==='expenses'){required($d,['date','category']);if(!in_array($d['category'],['Fuel','Repairs','Maintenance','Parts','Other'],true))throw new InvalidArgumentException('Invalid category.');if($d['category']==='Fuel'){required($d,['gallons','unit_price','odometer']);$d['gallons']=num($d['gallons'],'Gallons',0.000001);$d['unit_price']=num($d['unit_price'],'Price per gallon');$d['odometer']=num($d['odometer'],'Odometer');$d['amount']=round(num($d['gallons']*$d['unit_price'],'Fuel total'),2);$d['full']=!empty($d['full']);validate_observation($all,(int)$d['vehicle_id'],$id,$d['date'],$d['odometer'],$d['odometer'],$kind);}else{$d['amount']=round(num($d['amount']??null,'Amount'),2);foreach(['gallons','unit_price','odometer','full'] as $k)unset($d[$k]);}}
 if($kind==='drivers'){required($d,['name']);if(!empty($d['expires']))date_ok($d['expires'],'License expiration');$d['active']=!empty($d['active']);}
 if($kind==='driver_records'){required($d,['driver_id','date','type','notes']);ref_kind($d['driver_id'],'drivers');}
 if($kind==='mechanics')required($d,['name']);if($kind==='sale_templates')required($d,['name','jurisdiction']);
 if($kind==='invoices'){required($d,['mechanic_id','number','date','due_date','description']);ref_kind($d['mechanic_id'],'mechanics');date_ok($d['due_date'],'Due date');$d['amount']=round(num($d['amount']??null,'Invoice amount'),2);$paid=0;foreach($all as $r)if($r['kind']==='payments'&&(int)$r['data']['invoice_id']===$id)$paid+=(float)$r['data']['amount'];if($paid>$d['amount'])throw new InvalidArgumentException('Invoice cannot be less than payments already recorded.');}
 if($kind==='payments'){required($d,['invoice_id','date','amount']);$invoice=ref_kind($d['invoice_id'],'invoices');$paid=0;foreach($all as $r)if($r['kind']==='payments'&&$r['id']!==$id&&(int)$r['data']['invoice_id']===(int)$d['invoice_id'])$paid+=(float)$r['data']['amount'];$d['amount']=round(num($d['amount'],'Payment',0.01),2);if($paid+$d['amount']>(float)$invoice['amount']+0.00001)throw new InvalidArgumentException('Payment exceeds remaining balance of '.number_format((float)$invoice['amount']-$paid,2).'.');}
 if($kind==='engines'){required($d,['date','odometer','engine_miles']);$d['odometer']=num($d['odometer'],'Installation odometer');$d['engine_miles']=num($d['engine_miles'],'Engine miles at installation');validate_observation($all,(int)$d['vehicle_id'],$id,$d['date'],$d['odometer'],$d['odometer'],$kind);}
 if($kind==='inspections'){
 $d['status']=$d['status']??'Draft';if(!in_array($d['status'],['Draft','Completed'],true))throw new InvalidArgumentException('Invalid inspection status.');if(!empty($d['date'])){$date=new DateTimeImmutable(date_ok($d['date']));$d['week']=$date->modify('monday this week')->format('Y-m-d');$d['next_due']=$date->modify('monday next week')->format('Y-m-d');}if(isset($d['odometer'])&&$d['odometer']!=='')$d['odometer']=num($d['odometer'],'Odometer');$items=$d['items']??[];if(!is_array($items))throw new InvalidArgumentException('Checklist must be an object of results and notes.');foreach($items as $key=>$item){if(!isset(checklist()[$key])||!is_array($item)||!is_string($item['result']??'')||!is_string($item['notes']??''))throw new InvalidArgumentException('Invalid checklist item, result or notes.');}foreach(checklist() as $key=>$label){$v=$items[$key]??[];if(!empty($v['result'])&&!in_array($v['result'],['Pass','Needs attention','Fail','N/A'],true))throw new InvalidArgumentException('Invalid checklist result.');if($d['status']==='Completed'){if(empty($v['result']))throw new InvalidArgumentException($label.': choose a result.');if(in_array($v['result'],['Needs attention','Fail'],true)&&trim($v['notes']??'')==='')throw new InvalidArgumentException($label.': explain the finding.');}}if($d['status']==='Completed'){if(($d['unit']??'')!==config()['unit'])throw new InvalidArgumentException('Inspection unit must match the site odometer unit.');required($d,['vehicle_id','inspector','date','time','odometer']);if(empty($d['acknowledged']))throw new InvalidArgumentException('Inspector must explicitly acknowledge completion.');if(!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/D',$d['time']))throw new InvalidArgumentException('Enter inspection time.');validate_observation($all,(int)$d['vehicle_id'],$id,$d['date'],$d['odometer'],$d['odometer'],$kind);$d['completed_at']=gmdate('c');}$d['reference']=$d['reference']??('WI-'.strtoupper(bin2hex(random_bytes(8))));
 }
 if($kind==='issues'){required($d,['inspection_id','item','status']);$i=ref_kind($d['inspection_id'],'inspections');if(!isset(checklist()[$d['item']]))throw new InvalidArgumentException('Invalid checklist item.');if(!in_array($d['status'],['Open','In progress','Resolved'],true))throw new InvalidArgumentException('Invalid follow-up status.');if($d['status']==='Resolved'){required($d,['action','responsible','resolved_date']);date_ok($d['resolved_date']);}}
 if($kind==='sales'){
 $d['status']=$d['status']??'Draft';if(!in_array($d['status'],['Draft','Finalized','Signed'],true))throw new InvalidArgumentException('Invalid agreement status.');if($d['status']==='Signed')throw new InvalidArgumentException('Electronic signing is not supported. Print the finalized agreement for handwritten signatures.');foreach(['price','deposit'] as $key)if(isset($d[$key])&&$d[$key]!=='')$d[$key]=round(num($d[$key],ucfirst($key)),2);if(isset($d['price'],$d['deposit'])&&is_numeric($d['price'])&&is_numeric($d['deposit'])){$d['balance']=round($d['price']-$d['deposit'],2);if($d['balance']<0)throw new InvalidArgumentException('Deposit exceeds sale price.');}$d['reference']=$d['reference']??('BOS-'.strtoupper(bin2hex(random_bytes(8))));if($d['status']==='Finalized'){required($d,['buyer_name','buyer_address','seller_name','seller_address','date','time','location','year','make','model','vin','odometer','unit','disclosure','price','deposit','currency','payment_method','payment_status','payment_terms','condition','defects','accessories','title_liens','delivery','warranty','additional_terms','jurisdiction']);if(!in_array($d['disclosure'],['Actual mileage','Exceeds mechanical limits','Not actual mileage'],true))throw new InvalidArgumentException('Select mileage disclosure.');num($d['odometer'],'Odometer');if(!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/D',$d['time']))throw new InvalidArgumentException('Enter a valid sale time.');if(!in_array($d['unit'],['mi','km'],true)||!preg_match('/^[A-Z]{3}$/D',$d['currency']))throw new InvalidArgumentException('Choose mi/km and a three-letter currency code.');if(!empty($d['payment_due']))date_ok($d['payment_due'],'Payment due date');if(empty($d['reviewed']))throw new InvalidArgumentException('Review all terms and explicitly confirm.');$d['finalized_at']=gmdate('c');}}
 return $d;
}
function dashboard(array $rows): array {
 $out=['vehicles'=>[],'trip_count'=>0,'distance'=>0,'expenses'=>0,'debt'=>0,'fuel'=>[],'drivers'=>[],'invoices'=>[]];$by=[];foreach($rows as $r)$by[$r['kind']][]=$r;
 foreach($by['trips']??[] as $r){$out['trip_count']++;$out['distance']+=(float)$r['data']['end']-(float)$r['data']['start'];}
 foreach($by['expenses']??[] as $r)$out['expenses']+=(float)($r['data']['amount']??0);
 foreach($by['invoices']??[] as $r){$d=$r['data'];$paid=0;foreach($by['payments']??[] as $p)if((int)$p['data']['invoice_id']===$r['id'])$paid+=(float)$p['data']['amount'];$balance=round((float)$d['amount']-$paid,2);$linked=array_filter($by['expenses']??[],fn($e)=>(int)($e['data']['invoice_id']??0)===$r['id']);if(!$linked)$out['expenses']+=(float)$d['amount'];$out['debt']+=$balance;$out['invoices'][(string)$r['id']]=['paid'=>$paid,'balance'=>$balance,'status'=>$balance<=0?'Paid':($d['due_date']<date('Y-m-d')?'Overdue':($paid>0?'Partial':'Unpaid'))];}
 foreach($by['vehicles']??[] as $r){$d=$r['data'];$od=(float)$d['odometer'];foreach(observations($rows,$r['id']) as $o)$od=max($od,$o['max']);$engines=array_values(array_filter($by['engines']??[],fn($e)=>(int)$e['data']['vehicle_id']===$r['id']));usort($engines,fn($a,$b)=>[$a['data']['odometer'],$a['data']['date'],$a['id']]<=>[$b['data']['odometer'],$b['data']['date'],$b['id']]);$history=[['date'=>$d['baseline_date'],'odometer'=>(float)$d['odometer'],'engine_miles'=>(float)($d['engine_miles']??0),'serial'=>'Original baseline']];foreach($engines as $e)$history[]=$e['data'];foreach($history as $i=>&$e){$end=isset($history[$i+1])?(float)$history[$i+1]['odometer']:$od;$e['current_miles']=(float)$e['engine_miles']+max(0,$end-(float)$e['odometer']);$e['retired']=isset($history[$i+1]);$e['retirement_date']=$history[$i+1]['date']??null;}unset($e);
 $week=(new DateTimeImmutable('today'))->modify('monday this week')->format('Y-m-d');$status='Not started';$last='';$unresolved=0;foreach($by['inspections']??[] as $ins){$x=$ins['data'];if((int)($x['vehicle_id']??0)!==$r['id'])continue;if(($x['status']??'Draft')==='Completed')$last=max($last,$x['date']);if(($x['week']??'')===$week){if($x['status']==='Completed'){$findings=count(array_filter($x['items']??[],fn($i)=>in_array($i['result']??'',['Needs attention','Fail'])));$status=$findings?'Completed with findings':'Completed with no findings';}elseif($status==='Not started')$status='Draft';}}
 foreach($by['issues']??[] as $issue){$x=$issue['data'];$ins=array_values(array_filter($by['inspections']??[],fn($i)=>$i['id']===(int)$x['inspection_id']));if($ins&&(int)($ins[0]['data']['vehicle_id']??0)===$r['id']&&$x['status']!=='Resolved')$unresolved++;}
 $out['vehicles'][(string)$r['id']]=['odometer'=>$od,'engine_miles'=>end($history)['current_miles'],'engines'=>$history,'weekly_status'=>$status,'last_inspection'=>$last,'missing_this_week'=>$status==='Not started'||$status==='Draft','unresolved'=>$unresolved];
 $fuel=array_values(array_filter($by['expenses']??[],fn($e)=>(int)$e['data']['vehicle_id']===$r['id']&&$e['data']['category']==='Fuel'));usort($fuel,fn($a,$b)=>[$a['data']['date'],(float)($a['data']['odometer']??0),$a['id']]<=>[$b['data']['date'],(float)($b['data']['odometer']??0),$b['id']]);$base=null;$gallons=0;$valid=true;foreach($fuel as $f){$x=$f['data'];$mpg=null;if(!isset($x['gallons'],$x['odometer'],$x['full'])||!is_numeric($x['gallons'])||(float)$x['gallons']<=0){$base=null;$gallons=0;$valid=false;$out['fuel'][(string)$f['id']]=null;continue;}if($base!==null)$gallons+=(float)$x['gallons'];if($x['full']){if($base!==null&&$valid&&$gallons>0){$distance=(float)$x['odometer']-$base;if((config()['unit']??'mi')==='km')$distance/=1.609344;$mpg=round($distance/$gallons,2);}$base=(float)$x['odometer'];$gallons=0;$valid=true;}$out['fuel'][(string)$f['id']]=$mpg;}}
 foreach($by['drivers']??[] as $r){$trips=array_filter($by['trips']??[],fn($t)=>(int)($t['data']['driver_id']??0)===$r['id']);$out['drivers'][(string)$r['id']]=['trips'=>count($trips),'distance'=>array_sum(array_map(fn($t)=>(float)$t['data']['end']-(float)$t['data']['start'],$trips)),'expired'=>!empty($r['data']['expires'])&&$r['data']['expires']<date('Y-m-d')];}return $out;
}
function save_record(string $kind,array $d,int $id,int $version,int $uid,bool $internal=false): array {
 $all=records();$old=$id?record($id):null;if($kind==='expenses'&&!$internal&&(!empty($d['invoice_id'])||!empty($old['data']['invoice_id'])))throw new InvalidArgumentException('This repair expense is linked to an invoice. Edit the invoice instead.');$d['created_by']=$old['data']['created_by']??$uid;if(in_array($kind,['sales','inspections'],true)){if($old&&isset($old['data']['reference']))$d['reference']=$old['data']['reference'];else unset($d['reference']);if($old&&isset($old['data']['paper_signing']))$d['paper_signing']=$old['data']['paper_signing'];else unset($d['paper_signing']);}if($old&&($old['kind']!==$kind||$old['version']!==$version))throw new InvalidArgumentException('This record changed in another interface. Refresh and merge your changes; your form has been retained.');if($old&&$kind==='sales'&&$old['data']['status']!=='Draft')throw new InvalidArgumentException('Finalized snapshots are locked. Create an identified revision.');if($old&&$kind==='inspections'&&$old['data']['status']==='Completed')throw new InvalidArgumentException('Submitted inspection is immutable. Create a revision; original remains available.');
 if($old&&$kind==='issues'){foreach(['inspection_id','item','original_result','original_notes'] as $key)if(array_key_exists($key,$old['data']))$d[$key]=$old['data'][$key];}$d=validate($kind,$d,$id,$all);$now=gmdate('c');if($old){sql(db(),'UPDATE records SET payload=?,version=version+1,updated=? WHERE id=?',[json_encode($d),$now,$id]);}else{sql(db(),'INSERT INTO records(kind,payload,created,updated) VALUES(?,?,?,?)',[$kind,json_encode($d),$now,$now]);$id=(int)db()->lastInsertId();}sql(db(),'INSERT INTO revisions(record_id,user_id,payload,action,created) VALUES(?,?,?,?,?)',[$id,$uid,json_encode(['before'=>$old,'after'=>$d]),$old?'edit':'create',$now]);
 if($kind==='invoices'){$linked=null;foreach($all as $row)if($row['kind']==='expenses'&&(int)($row['data']['invoice_id']??0)===$id){$linked=$row;break;}$mechanic=ref_kind($d['mechanic_id'],'mechanics');save_record('expenses',['vehicle_id'=>$d['vehicle_id'],'date'=>$d['date'],'category'=>'Repairs','vendor'=>$mechanic['name'],'description'=>'Invoice '.$d['number'].': '.$d['description'],'amount'=>$d['amount'],'invoice_id'=>$id,'notes'=>'Canonical linked repair expense. Payments affect debt only.'],$linked['id']??0,$linked['version']??0,$uid,true);}
 if($kind==='inspections'&&$d['status']==='Completed'){foreach($d['items'] as $key=>$v)if(in_array($v['result'],['Needs attention','Fail'],true))save_record('issues',['inspection_id'=>$id,'item'=>$key,'status'=>'Open','original_result'=>$v['result'],'original_notes'=>$v['notes'],'notes'=>''],0,0,$uid);}
 return record($id);
}
